// SPDX-License-Identifier: Apache-2.0
import { Bitmap, Sprite, createAssetRef, createAssetType, createTexture, isTexture, createImageData2D } from '@egret/engine';
import { installPlayerProject } from '@egret/android-player-project';
async function create({engine,scope,publishPage}) {
  const type=createAssetType('churn-tile',isTexture);
  const bindings=new Map();
  let loaded=0,released=0;
  engine.assets.register(type,{
    load(ref){
      const seed=ref.id==='warm'?3:19, pixels=new Uint8Array(16*16*4);
      for(let y=0;y<16;y++)for(let x=0;x<16;x++){
        const j=(y*16+x)*4;
        pixels[j]=(x*12+y*7+seed)%256;pixels[j+1]=(y*16+seed*4)%256;pixels[j+2]=(x*5+seed*10)%256; pixels[j+3]=255;
      }
      const image=createImageData2D({width:16,height:16,pixels});
      const texture=createTexture(image);
      bindings.set(texture,publishPage(seed===3?1:2,image));loaded++;
      return texture;
    },
    dispose(texture){bindings.get(texture).release();bindings.delete(texture);texture.dispose();released++}
  });
  const [a,b]=await engine.createAssetGroup(scope,['warm','cool'].map(id=>createAssetRef(type,id))).ready;
  const nodes=[];
  for(let i=0;i<81;i++){
    let node;
    if(i%3===0){
      node=new Sprite();node.graphics.beginFill((0x336644+i*911)&0xffffff).drawRect(0,0,16,16).endFill();
    }else{node=new Bitmap(i%3===1?a:b)}
    engine.stage.addChild(scope.use(node));nodes.push(node);
  }
  return {
    update(elapsedMs){
      const f=Math.round(elapsedMs*120/1000);
      for(let i=0;i<nodes.length;i++){
        const node=nodes[i];node.x=9+(i%9)*38+((f+i*3)%9);
        node.y=19+Math.floor(i/9)*64+((f*3+i)%11);
      }
    },
    closedSnapshot(){return {texturesLoaded:loaded,texturesReleased:released,quads:81}}
  };
}
installPlayerProject({width:360,height:640,clearColor:0x172125,create});

