// Private diagnostic build. Preserve the original capture and invoke its exact encoder once per frame.
import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';
export function hook(source,baseline,mode){
 const code=baseline?'let N=Ff(o.captureSharedFrame(s),d,n);':'let A=n.encode(c.captureSharedFrame(o),p,r);';
 const lhs=baseline?'N':'A',capture=baseline?'o.captureSharedFrame(s)':'c.captureSharedFrame(o)',fid=baseline?'d':'p',encode=baseline?'Ff(__churnFrame,d,n)':'n.encode(__churnFrame,p,r)';
 assert.equal(source.split(code).length,2,'Expected exactly one SDK encoder call');
 const body=mode==='oracle'?'const __churnFrame='+capture+';globalThis.__oracle(__churnFrame,'+fid+');let '+lhs+'='+encode+';':
 'const __churnFrame='+capture+';const __churnStart=performance.now();let '+lhs+'='+encode+';const __churnEnd=performance.now();globalThis.__encodeSample('+fid+',__churnStart,__churnEnd);';
 const setup=mode==='oracle'?'':`(()=>{
 const native=globalThis.EgretNativePlayer;
 const rows=new Array(180), cal=()=>{const values=[];let a=performance.now();for(let i=0;i<64;i++){const b=performance.now();values.push(Math.round((b-a)*1000));a=b;}return values;};
 const before=cal();
 globalThis.__encodeSample=(id,a,b)=>{
  if(id>=30&&id<210)rows[id-30]=Math.round((b-a)*1000);
  if(id===209)setTimeout(()=>{native.state(JSON.stringify({name:"encodeChurn81",first:30,last:209,encodeUs:rows,clockBeforeUs:before,clockAfterUs:cal()}));},80);
 };
})();\n`;
 return setup+source.replace(code,body);
}
if(process.argv[1]&&path.resolve(process.argv[1])===import.meta.filename){
 const lane=process.argv[2];assert(/^(standard|trimmed)(base|current)probe$/.test(lane));const dir=path.join(import.meta.dirname,lane,'app/src/main');
 const js=path.join(dir,'assets/game/game.js'),activity=path.join(dir,'java/org/egret/example/LibraryActivity.java');
 const source=fs.readFileSync(js,'utf8');fs.writeFileSync(js,hook(source,lane.includes('base'),'timed'));
 let java=fs.readFileSync(activity,'utf8').replaceAll('\r\n','\n');
 const before='        writer.println(prefix + "Egret player: " + (player == null ? lastClose : player.getDiagnostics()));';
 assert.equal(java.split(before).length,2);java=java.replace('    private String lastClose = "{}";','    private String lastClose = "{}";\n    private String probeRow;').replace('            @Override public void onReady()', '            @Override public void onState(String json) { probeRow = json; }\n            @Override public void onReady()').replace(before,
 '        try { org.json.JSONObject data = player == null ? new org.json.JSONObject(lastClose) : player.getDiagnostics(); if (probeRow != null) data.put("churnProbe", new org.json.JSONObject(probeRow)); writer.println(prefix + "Egret player: " + data); } catch(org.json.JSONException e) { throw new IllegalStateException(e); }');
 fs.writeFileSync(activity,java);
}

