// Independent packet and texture oracle. The SDK does not participate in makePacket or tape.
import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import vm from 'node:vm';import crypto from 'node:crypto';
import {hook} from './instrument.mjs';
const lab=import.meta.dirname,sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const source=lane=>fs.readFileSync(path.join(lab,lane,'app/src/main/assets/game/game.js'),'utf8');
const p4=n=>{const b=Buffer.alloc(4);b.writeInt32BE(n);return b};
const pages=[3,19].map(seed=>{const x=Buffer.alloc(1024);for(let y=0;y<16;y++)for(let z=0;z<16;z++){let i=(y*16+z)*4;x[i]=(z*12+y*7+seed)%256;x[i+1]=(y*16+seed*4)%256;x[i+2]=(z*5+seed*10)%256;x[i+3]=255;}return x});
const loc=(t,i)=>[9+(i%9)*38+(t+i*3)%9,19+Math.floor(i/9)*64+(t*3+i)%11];
const recordColor=i=>i%3===0?(0x336644+i*911)&0xffffff:0xffffff;
function makePacket(t){
 const p=Buffer.alloc(24+64*81),h=[0x32524745,t,360,640,0x172125ff,81];
 h.forEach((n,i)=>p.writeUInt32LE(n,i*4));
 for(let i=0;i<81;i++){const b=24+i*64,slot=i%3,c=recordColor(i),[x,y]=loc(t,i);
  p[b]=slot;p[b+1]=c>>>16;p[b+2]=c>>>8;p[b+3]=c;
  [1,x,y,x+16,y,x,y+16,0,0,1,1,0,0,360,640].forEach((v,j)=>p.writeFloatLE(v,b+4+4*j));
 }return p;
}
const packets=Array.from({length:210},(_,t)=>makePacket(t));
const data=[p4(0x45475250),p4(1),p4(360),p4(640),p4(210)];
for(let t=0;t<210;t++){if(t){data.push(p4(-1))}else{data.push(p4(2));for(let i=0;i<2;i++){data.push(Buffer.from([i+1]),p4(i+1),p4(16),p4(16),pages[i]);}}
 data.push(p4(packets[t].length),packets[t]);}
const payload=Buffer.concat(data);const tape=Buffer.concat([payload,Buffer.from(sha(payload),'hex')]);
let pairsChanged=0;
for(let t=1;t<210;t++)for(let i=0;i<81;i++){const at=24+64*i;assert(!packets[t-1].subarray(at,at+64).equals(packets[t].subarray(at,at+64)));pairsChanged++;}
const verified=[];
for(const lane of ['standardbase','standardcurrent','trimmedbase','trimmedcurrent']){
 let prev=null,identities=0,frames=0;const projectState=[],released=[],seen=new Map();
 const sandbox={AbortController,queueMicrotask,performance,setTimeout,clearTimeout,btoa,console,EgretNativePlayer:{
   state:s=>projectState.push(JSON.parse(s)),page:(id,w,h,b)=>{assert.equal(w,16);assert.equal(h,16);assert(Buffer.from(b,'base64').equals(pages[id-1]));seen.set(id,true)},releasePage:id=>released.push(id)},
 __oracle(frame,id){assert.equal(frames++,id);const commands=frame.commands.filter(c=>c.kind==='image'||c.kind==='rect');assert.equal(commands.length,81);
   if(prev)for(let k=0;k<81;k++){assert.notEqual(commands[k],prev[k]);identities++}prev=commands;}
 };vm.createContext(sandbox);new vm.Script(hook(source(lane),lane.includes('base'),'oracle')).runInContext(sandbox);const game=sandbox.EgretPlayerProject;await game.start();
 for(let t=0;t<210;t++){const packet=Buffer.from(game.frame(t*1000/120));try{assert(packet.equals(packets[t]))}catch(e){const off=packet.findIndex((v,i)=>v!==packets[t][i]);throw Error(lane+' frame '+t+' first difference '+off+' actual '+packet[off]+' expected '+packets[t][off]);}}
 await game.close();assert.equal(identities,16929);assert.equal(seen.size,2);assert.deepEqual(released.toSorted(),[1,2]);verified.push({lane,frames,changedCommandIdentitiesComparedToPreviousFrame:identities});
}
const pixels=Buffer.alloc(1080*1920*4);for(let i=0;i<pixels.length;i+=4){pixels[i]=0x17;pixels[i+1]=0x21;pixels[i+2]=0x25;pixels[i+3]=255;}
for(let i=0;i<81;i++){const [x,y]=loc(209,i),slot=i%3,c=recordColor(i);
 for(let dy=0;dy<48;dy++)for(let dx=0;dx<48;dx++){const off=((y*3+dy)*1080+x*3+dx)*4;
 if(!slot){pixels[off]=c>>>16;pixels[off+1]=c>>>8;pixels[off+2]=c}else{const p=(Math.floor(dy/3)*16+Math.floor(dx/3))*4;pages[slot-1].copy(pixels,off,p,p+4)}}}
const colors=new Set();for(let i=0;i<pixels.length;i+=4)colors.add(pixels.readUInt32BE(i));
if(process.argv.includes('--raw-viewport')) fs.writeFileSync(path.join(lab,'ideal-viewport.rgba'),pixels);
const result={frameIds:[0,209],quadsPerFrame:81,bytesPerFrame:5208,changedRecordsIn209Transitions:pairsChanged,distinctCommandBodies:new Set(packets.map(p=>sha(p.subarray(24)))).size,
 verified,tape:{fullTapeSha256:sha(tape),payloadSha256:sha(payload),tapeBytes:tape.length,commandStreamSha256:sha(Buffer.concat(packets))},
 viewport:{width:1080,height:1920,pixels:2073600,colors:colors.size,sha256:sha(pixels)},pixelStatus:'Independent ideal opaque texel layout, compare to physical GLES readback; compare all physical captures against base even if 8-bit render-target quantization differs.'};
fs.writeFileSync(path.join(lab,'oracle.json'),JSON.stringify(result,null,2)+'\n');fs.writeFileSync(path.join(lab,'expected.egrp'),tape);console.log(JSON.stringify(result));
